const items = $input.all();
const seen = new Set();
const stories = [];

for (const item of items) {
  const j = item.json;
  const title = (j.title || '').trim();
  const link = (j.link || j.guid || '').trim();
  const key = (link || title).toLowerCase();
  if (!title || !key || seen.has(key)) continue;
  seen.add(key);
  stories.push({
    title,
    link,
    summary: (j.contentSnippet || j.content || j.description || '').toString().slice(0, 500),
    published: j.pubDate || j.isoDate || null,
    source: j.creator || j.author || (link ? new URL(link).hostname.replace('www.', '') : 'unknown')
  });
}

return [{
  json: {
    collected_at: new Date().toISOString(),
    story_count: stories.length,
    stories: stories.slice(0, 40)
  }
}];

