function extractJson(text) {
  if (!text) throw new Error('Empty AI response');
  if (typeof text === 'object') return text;
  const cleaned = String(text).replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
  try { return JSON.parse(cleaned); } catch (e) {}
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start >= 0 && end > start) return JSON.parse(cleaned.slice(start, end + 1));
  throw new Error('Could not parse JSON from AI response: ' + cleaned.slice(0, 200));
}

const raw = $input.first().json;
const content = raw.message?.content || raw.text || raw;
const parsed = extractJson(content);

const postText = (parsed.post_text || '').trim();
if (!postText) throw new Error('Founder Voice Agent did not return post_text');

const hashtags = Array.isArray(parsed.hashtags) ? parsed.hashtags.join(' ') : '';
const fullPost = hashtags && !postText.includes('#') ? `${postText}\n\n${hashtags}` : postText;

return [{
  json: {
    chosen_style: parsed.chosen_style || '',
    post_text: fullPost,
    hook: parsed.hook || fullPost.split('\n')[0],
    image_prompt: parsed.image_prompt || 'Minimal professional abstract technology concept, clean LinkedIn aesthetic, no text',
    hashtags: parsed.hashtags || [],
    source_title: parsed.source_title || '',
    source_link: parsed.source_link || '',
    generated_at: new Date().toISOString()
  }
}];

const draft = $('Parse Final Post JSON').first().json;
const imageItem = $input.first().json;

// OpenAI image node may return url or binary depending on version/settings
const imageUrl = imageItem.url || imageItem.data?.[0]?.url || imageItem.message?.content || null;

return [{
  json: {
    ...draft,
    image_url: imageUrl,
    approval_message: [
      '🧠 *Meghan Vaze / Unovative — LinkedIn draft ready*',
      '',
      `*Hook:* ${draft.hook}`,
      `*Style:* ${draft.chosen_style}`,
      draft.source_title ? `*Source:* ${draft.source_title}` : null,
      draft.source_link ? draft.source_link : null,
      '',
      '---- POST ----',
      draft.post_text,
      '--------------',
      '',
      imageUrl ? `Image: ${imageUrl}` : 'Image: (check binary/attachment in n8n)',
      '',
      'Approve to publish, or Reject to regenerate.'
    ].filter(Boolean).join('\n')
  },
  binary: $input.first().binary || undefined
}];

const approval = $input.first().json;
const draft = $('Prepare Approval Payload').first().json;

// n8n Send-and-Wait approval usually exposes data.approved boolean
const approved = Boolean(
  approval?.data?.approved ??
  approval?.approved ??
  (String(approval?.data?.action || approval?.action || '').toLowerCase().includes('approve'))
);

const feedback = approval?.data?.text || approval?.text || approval?.data?.message || '';

return [{
  json: {
    approved,
    feedback,
    post_text: draft.post_text,
    hook: draft.hook,
    image_url: draft.image_url,
    source_title: draft.source_title,
    source_link: draft.source_link,
    chosen_style: draft.chosen_style,
    generated_at: draft.generated_at
  },
  binary: $('Prepare Approval Payload').first().binary || undefined
}];

